function phonePreview() {
  return `<div class="phone" aria-label="Super Alarm ringing preview">
    <div class="phone-screen">
      <div class="ring-stage">
        <span class="ripple"></span><span class="ripple"></span><span class="ripple"></span>
        <div class="bell">${icon("bellFill")}</div>
        <div class="ring-time"><strong>6:30</strong><span>Time to get up</span></div>
      </div>
      <div class="dismiss">${icon("qr")} Scan QR to stop</div>
    </div>
  </div>`;
}

function imageResponse(base64, contentType) {
  const bytes = Uint8Array.from(atob(base64), char => char.charCodeAt(0));
  return new Response(bytes, {
    headers: {
      "content-type": contentType,
      "cache-control": "public, max-age=31536000, immutable",
    },
  });
}

